INSERT INTO `wp_comments` VALUES (2,63,'WooCommerce','woocommerce@escolesesportivesondara.local','','','2026-03-23 09:44:46','2026-03-23 08:44:46','Pendiente de pago por transferencia. El estado del pedido cambió de Pendiente de pago a En espera.',0,'1','WooCommerce','order_note',0,0);
